/**
 * Institutional Canvas OAuth config — per-school Developer Key credentials.
 *
 * Stored in `lms_institution_configs`, which denies all access to
 * authenticated/anon (RLS + revoked grants). Every function here therefore
 * requires the SERVICE-ROLE client. The non-secret reader
 * (`getInstitutionCanvasConfig`) deliberately omits `client_secret` from its
 * return shape so callers can't accidentally leak it into a page payload; use
 * `getInstitutionCanvasSecret` only on the OAuth token-exchange path.
 *
 * This is the *app* credential. Per-teacher OAuth *tokens* live in
 * `lms_connections` (scope='oauth'). See docs/canvas-institutional-oauth.md.
 */
import type { SupabaseClient } from "@supabase/supabase-js";
import type { Database } from "$lib/database.types";
import type { InstitutionCanvasConfigInput } from "./validation";

type DB = SupabaseClient<Database>;

const SERVICE = "canvas";

/** Non-secret view of an institutional Canvas OAuth config. */
export interface InstitutionCanvasConfig {
  id: string;
  schoolId: string;
  domain: string;
  clientId: string;
  enabled: boolean;
  updatedAt: string;
}

/**
 * Read a school's Canvas OAuth config WITHOUT the secret. Safe to surface in an
 * admin page payload. Returns null if none configured. Requires service-role.
 */
export async function getInstitutionCanvasConfig(
  serviceRole: DB,
  schoolId: string,
): Promise<InstitutionCanvasConfig | null> {
  const { data, error } = await serviceRole
    .from("lms_institution_configs")
    .select("id, school_id, domain, client_id, enabled, updated_at")
    .eq("school_id", schoolId)
    .eq("service", SERVICE)
    .maybeSingle();
  if (error) throw error;
  if (!data) return null;
  return {
    id: data.id,
    schoolId: data.school_id,
    domain: data.domain,
    clientId: data.client_id,
    enabled: data.enabled,
    updatedAt: data.updated_at,
  };
}

