<div class="rubric-canvas flex h-full flex-col bg-surface text-[13px] text-ink">
  <!-- toolbar -->
  <div
    class="@container flex h-[2.375rem] flex-none items-center gap-2 border-b border-line-strong bg-canvas-warm px-3 py-1.5"
  >
    {#if onPickTemplate}
      <div class="relative">
        <button
          onclick={() => (templateOpen = !templateOpen)}
          use:tip={"Start from a pre-baked rubric"}
          class="inline-flex items-center gap-1 whitespace-nowrap rounded-md border border-line-strong bg-surface px-2 py-1 text-xs text-ink-muted hover:border-brand-300 hover:text-brand-700"
          ><LayoutTemplate class="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
          <span class="hidden @[32rem]:inline">Template</span>
          <ChevronDown class="h-3 w-3" aria-hidden="true" /></button
        >
        {#if templateOpen}
          <button
            class="fixed inset-0 z-20 cursor-default"
            aria-label="close"
            onclick={() => (templateOpen = false)}
          ></button>
          <div
            class="absolute left-0 top-9 z-30 max-h-[60vh] w-72 overflow-auto rounded-xl border border-line-strong bg-white p-1.5 shadow-xl"
          >
            <div
              class="px-2 pb-1 pt-1 text-[10px] font-semibold uppercase tracking-wider text-ink-subtle"
            >
              Template library
            </div>
            {#each templates as t (t.id)}
              <button
                onclick={() => {
                  onPickTemplate?.(t.id, "builtin");
                  templateOpen = false;
                }}
                class="block w-full rounded-lg px-2.5 py-1.5 text-left hover:bg-brand-50"
              >
                <div class="text-[12.5px] font-semibold text-ink">{t.name}</div>
                <div class="text-[10.5px] leading-snug text-ink-subtle">
                  {t.blurb}
                </div>
              </button>
            {/each}
            {#if savedRubrics.length}
              <div class="my-1 border-t border-line"></div>
              <div
                class="px-2 pb-1 pt-1 text-[10px] font-semibold uppercase tracking-wider text-ink-subtle"
              >
                From your saved rubrics
              </div>
              {#each savedRubrics as r (r.id)}
                <button
                  onclick={() => {
                    onPickTemplate?.(r.id, "saved");
                    templateOpen = false;
                  }}
                  class="block w-full truncate rounded-lg px-2.5 py-1.5 text-left text-[12.5px] text-ink hover:bg-brand-50"
                  >{r.name}</button
                >
              {/each}
            {/if}
            {#if onSaveTemplate}
              <div class="my-1 border-t border-line"></div>
              <button
                onclick={() => {
                  onSaveTemplate?.();
                  templateOpen = false;
                }}
                class="flex w-full items-center gap-1.5 rounded-lg px-2.5 py-1.5 text-left text-[12px] text-brand-700 hover:bg-brand-50"
                ><Plus class="h-3.5 w-3.5" aria-hidden="true" /> Save this rubric
                as a template</button
              >
            {/if}
          </div>
        {/if}
      </div>
    {/if}

    {#if onUpload}
      <button
        onclick={onUpload}
        disabled={uploadBusy}
        use:tip={"Import a rubric from a file"}
        class="inline-flex items-center gap-1 whitespace-nowrap rounded-md border border-line-strong bg-surface px-2 py-1 text-xs text-ink-muted hover:border-brand-300 hover:text-brand-700 disabled:opacity-60"
      >
        {#if uploadBusy}
          <ThinkingIndicator active verbs={EXTRACT_VERBS} />
        {:else}
          <Upload class="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
          <span class="hidden @[32rem]:inline">Upload</span>
        {/if}
      </button>
    {/if}

    {#if (onPickTemplate || onUpload) && (onUndo || onRedo)}
      <span class="mx-0.5 h-5 w-px bg-line-strong"></span>
    {/if}

    {#if onUndo || onRedo}
      <button
        onclick={onUndo}
        disabled={!canUndo}
        use:tip={undoTip}
        aria-label="Undo"
        class="inline-flex items-center rounded-md border border-line-strong bg-surface px-2 py-1 text-ink-muted hover:border-brand-300 hover:text-brand-700 disabled:opacity-40"
      >
        <Undo2 class="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
      </button>
      <button
        onclick={onRedo}
        disabled={!canRedo}
        use:tip={redoTip}
        aria-label="Redo"
        class="inline-flex items-center rounded-md border border-line-strong bg-surface px-2 py-1 text-ink-muted hover:border-brand-300 hover:text-brand-700 disabled:opacity-40"
      >
        <Redo2 class="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
      </button>
    {/if}

    <!-- Add criterion + Balance sit right next to Undo/Redo as icon-only tools. -->
    <button
      onclick={doAddRoot}
      data-testid="rubric-add-criterion"
      use:tip={"Add a top-level criterion"}
      aria-label="Add criterion"
      class="inline-flex items-center rounded-md border border-brand-300 bg-brand-50 px-2 py-1 text-brand-700 hover:border-brand-600 hover:bg-brand-100"
      ><Plus class="h-3.5 w-3.5 shrink-0" aria-hidden="true" /></button
    >

    <!-- Balance even-splits the authored WEIGHTS to 100%. It only makes sense in
         weights mode: in points mode the worths come from each scale's max and the
         weights already sum to 100 by construction, so balancing there would flatten
         the point worths and re-introduce the scale↔points mismatch. -->
    {#if driving === "weights"}
      <button
        onclick={balance}
        use:tip={"Balance the weights to 100%"}
        aria-label="Balance to 100%"
        class="inline-flex items-center rounded-md border border-line-strong bg-surface px-2 py-1 text-ink-muted hover:border-brand-300 hover:text-brand-700"
        ><ScaleIcon class="h-3.5 w-3.5 shrink-0" aria-hidden="true" /></button
      >
    {/if}

    {#if onToggleAssistant || onToggleGrade}
      <!-- thinner divider between the editing tools and the panel toggles -->
      <span class="mx-1 h-4 w-px bg-line"></span>
      <div class="flex shrink-0 overflow-hidden rounded-md border border-line">
        {#if onToggleAssistant}
          <PanelToggle
            icon={Sparkles}
            label="Assistant"
            active={assistantOpen}
            onclick={onToggleAssistant}
            tipText="Rubric assistant"
            labelClass="hidden @[32rem]:inline"
          />
        {/if}
        {#if onToggleAssistant && onToggleGrade}
          <span class="w-px self-stretch bg-line"></span>
        {/if}
        {#if onToggleGrade}
          <PanelToggle
            icon={ListChecks}
            label="Preview"
            active={gradeOpen}
            onclick={onToggleGrade}
            tipText="Grading preview: the exact widget you grade with"
            labelClass="hidden @[32rem]:inline"
          />
        {/if}
      </div>
    {/if}

    <span class="flex-1"></span>

    <!-- right edge: AI notes, Rubrics 101, Start over (all icon-only) -->
